CREATE OR REPLACE PROCEDURE sp(
    arg1 INTEGER,
    arg2 TEXT,
    arg3 TEXT,
    arg4 INTEGER,
    arg5 TEXT,
    arg6 INTEGER
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_threshold INTEGER := arg1;
    v_status TEXT := arg2;
    v_operation TEXT := arg3;
    v_handled_count INTEGER := 0;
    v_batch_size INTEGER := 10;
    v_state TEXT := 'INIT';
    v_high_priority_seen BOOLEAN := FALSE;
    v_initial_threshold INTEGER := arg1;
    rec RECORD;
BEGIN
    IF v_initial_threshold < 3 THEN
        v_state := 'MINIMAL_PROCESS';

        FOR rec IN
            SELECT "ResID" AS num, "ResName" AS name, "Address" AS street_loc
            FROM "Restaurant"
            WHERE "ResID" < arg1 AND "ResName" LIKE arg2
        LOOP
            v_handled_count := v_handled_count + 1;

            IF rec.num > 25 THEN
                UPDATE "Restaurant" SET "ResName" = 'PROMOTED' WHERE "ResID" = rec.num;
            ELSIF rec.street_loc = v_operation THEN
                DELETE FROM "Visits_Restaurant" WHERE "ResID" = rec.num;
                DELETE FROM "Type_Of_Restaurant" WHERE "ResID" = rec.num;
                DELETE FROM "Restaurant" WHERE "ResID" = rec.num AND "ResName" = rec.name;
            ELSE
                UPDATE "Restaurant" SET "Address" = 'PENDING' WHERE "ResID" = rec.num;
            END IF;

            IF v_handled_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

    ELSIF v_initial_threshold < 8 THEN
        v_state := 'STANDARD_PROCESS';

