            SELECT "StuID" AS num, "LName" AS lname, "city_code" AS city
            FROM "Student"
            WHERE "StuID" >= (arg4 - 5) AND "StuID" <= (arg4 + 15)
        LOOP
            v_handled_count := v_handled_count + 1;

            IF rec.city = v_operation THEN
                UPDATE "Student" SET "Sex" = 'U' WHERE "StuID" = rec.num;
            END IF;

            IF rec.lname = arg5 THEN
                UPDATE "Student" SET "city_code" = 'MATCHED' WHERE "StuID" = rec.num;
            END IF;

            IF rec.lname LIKE 'ACTIVE%' THEN
                UPDATE "Student" SET "LName" = 'PROCESSED' WHERE "StuID" = rec.num;
            ELSIF rec.num > (arg4 + 5) THEN
                v_threshold := v_threshold + rec.num;
            ELSE
                DELETE FROM "Student" WHERE "StuID" = rec.num AND "LName" = 'EXPIRED';
            END IF;

            IF v_handled_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

    ELSIF v_initial_threshold < 18 THEN
        v_state := 'ENHANCED_PROCESS';

        FOR rec IN
            SELECT "ResTypeID" AS num
            FROM "Restaurant_Type"
            WHERE "ResTypeID" > (arg6 - 20)
        LOOP
            v_handled_count := v_handled_count + 1;

            IF rec.num < 50 THEN
                v_status := 'LOW_PRIORITY';
            ELSIF rec.num < 150 THEN
                v_status := 'MEDIUM_PRIORITY';
            ELSE
                v_status := 'HIGH_PRIORITY';
                v_high_priority_seen := TRUE;
            END IF;

            UPDATE "Restaurant_Type" SET "ResTypeID" = ("ResTypeID" + 10)
            WHERE "ResTypeID" = rec.num;

            IF v_handled_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

    ELSIF v_initial_threshold < 25 THEN
        v_state := 'ARCHIVE_MODE';

        UPDATE "Restaurant" SET "Address" = 'ARCHIVED'
        WHERE "ResID" < arg1 AND "ResName" <> v_status;

